/**
 * コネクタ設定（秘密キーはマスク済み）
 */
export type DataSourceDtoConfig = {[key: string]: string};

/**
 * FR-05: 原本へ付与する既定 ABAC 文書属性（`confidentiality` 等）
 */
export type DataSourceDtoDefaultAttributes = {[key: string]: string};

/**
 * FR-05, SC-06（ADR-0074 決定 1 / #1194）: `owner` の**写像表**（データソース単位）。
 * キーが**ソース側の利用者識別子**、値が**基盤の利用者識別子**（ログイン名）である。
 * **既定属性（`defaultAttributes`）とは別の器**であり、片方の更新はもう片方を消さない。
 * **マスクしない**（対の両側とも識別子であり秘密ではない）。
 */
export type DataSourceDtoOwnerMappings = {[key: string]: string} | null;

/**
 * FR-01, UC-04, SC-06: データソース 1 件（`Knowledge.Contracts/Dtos/DataSourceDto.cs`）。
 * IADR-0053: `config` の**秘密キー（token / password / secret / credential を含むキー）は
 * 後段が `***` へマスク済み**である。SPA から秘密を埋め込むことはしない。
 * SC-06（planning#200 / 裁定 Q15）: `nextSyncAt` は**共通間隔の次回実行時刻**であり
 * **全ソースで同じ値**になる。ソース別スケジュールは持たない（IADR-0136）。
 * SC-06（同 裁定 Q14 / #537）: 同期健全性（`consecutiveFailureCount` / `retryLimit` /
 * `lastSyncError`）を持つ。`status` は健全性を表さない（`active` / `disabled` の設定状態のみ）。
 */
export interface DataSourceDto {
  id: string;
  name: string;
  /** コネクタ種別（`filesystem` / `wiki` / `saas` / `db` ほか） */
  sourceType: string;
  connectionUri: string;
  /** `active` / `disabled`。**同期の健全性は表さない** */
  status: string;
  lastSyncedAt?: string | null;
  /** コネクタ設定（秘密キーはマスク済み） */
  config: DataSourceDtoConfig;
  /** FR-05: 原本へ付与する既定 ABAC 文書属性（`confidentiality` 等） */
  defaultAttributes: DataSourceDtoDefaultAttributes;
  createdAt: string;
  /**
     * SC-06: 定期同期（全ソース共通の間隔）の**次回実行時刻**。**全ソースで同じ値**を返す。
     * 定期同期が無効なとき（`DataSourceSync:Enabled=false`。compose / dev の既定）は `null`。
     */
  nextSyncAt?: string | null;
  /**
     * SC-06（裁定 Q14 / #537）: UC-04 例外フローの**連続同期失敗回数**。完全成功で 0 へ戻る。
     * `retryLimit` に達した時点が「継続失敗」であり、アラート（構造化ログ `Alert=true`）が出る。
     * 画面はこの値と `retryLimit` から**琥珀（警告）**を描く。
     */
  consecutiveFailureCount: number;
  /**
     * SC-06（裁定 Q14 / #537）: 再試行上限。**継続失敗のしきい値そのもの**である
     * （計画「「継続失敗」のしきい値は再試行上限に達した時点とする」）。
     * 画面が「3/5」の分母を契約から得るために返す（画面へ定数を複写させない）。
     */
  retryLimit: number;
  /**
     * SC-06（裁定 Q14 / #537）: 直近の同期エラー。**後段が保存時点でマスク済み**である
     * （接続文字列・資格情報つき URI・`Bearer` トークンを伏せる。IADR-0053 と同じ守り）。
     */
  lastSyncError?: string | null;
  /** SC-06（裁定 Q14 / #537）: 直近の同期エラーの発生時刻。 */
  lastSyncErrorAt?: string | null;
  /**
     * FR-05, SC-06（ADR-0074 決定 1 / #1194）: `owner` の**写像表**（データソース単位）。
     * キーが**ソース側の利用者識別子**、値が**基盤の利用者識別子**（ログイン名）である。
     * **既定属性（`defaultAttributes`）とは別の器**であり、片方の更新はもう片方を消さない。
     * **マスクしない**（対の両側とも識別子であり秘密ではない）。
     */
  ownerMappings?: DataSourceDtoOwnerMappings;
}

