/**
 * 入力文書の最高機密区分（大文字小文字は無視）。越境マトリクスで呼び出し先を判定する。
 * 未指定（null/空）・未知の値は安全側の restricted に倒す（fail-safe, deny-by-default）。
 */
export type CompletionApiRequestConfidentiality = typeof CompletionApiRequestConfidentiality[keyof typeof CompletionApiRequestConfidentiality] | null;


export const CompletionApiRequestConfidentiality = {
  public: 'public',
  internal: 'internal',
  confidential: 'confidential',
  restricted: 'restricted',
} as const;

export interface CompletionApiRequest {
  prompt: string;
  /** 出力トークン上限。thinking（拡張思考）が既定で有効なモデル（Opus 5 / Sonnet 5 等）では 思考トークンと本文の合算上限になるため、既定は本文想定長＋思考の作業領域を見込んだ 4096 とする（IADR-0101）。小さすぎると本文が空または途中で切れる。 */
  maxTokens?: number;
  /** 明示要求モデル。null の場合はゲートウェイが用途（purpose）に応じて選択する */
  model?: string | null;
  /**
     * 入力文書の最高機密区分（大文字小文字は無視）。越境マトリクスで呼び出し先を判定する。
     * 未指定（null/空）・未知の値は安全側の restricted に倒す（fail-safe, deny-by-default）。
     */
  confidentiality?: CompletionApiRequestConfidentiality;
  /** 用途。null/空は default 扱い */
  purpose?: string | null;
}

/**
 * sent=false は機密区分による送信拒否（縮退）または呼び出し先不調を示す。
 * IADR-0104: sent（越境させたか）と stopReason（モデル側の終了理由）は独立した軸である。
 */
export interface CompletionApiResponse {
  text: string;
  model: string;
  inputTokens: number;
  outputTokens: number;
  sent: boolean;
  /** 選択・拒否した呼び出し先（監査・縮退表示用） */
  endpoint?: string | null;
  /** 選択・拒否の理由（監査・縮退表示用） */
  routingReason?: string | null;
  /**
     * ADR-0025, IADR-0104: 送信が成立した場合のモデル側の終了理由。
     * 未送信（sent=false）・`finish_reason` を返さないプロバイダでは null。既知の語彙は
     * `end_turn` / `max_tokens` / `refusal` / `stop_sequence` / `tool_use` だが、**閉じた enum にはしない**。
     * 語彙が増えたときに未知の値を弾かず、そのまま透過してログ・監査に残すためである。
     * IADR-0109 (#394): この語彙は**プロバイダ横断の正準語彙**（Anthropic の stop_reason 由来）である。
     * OpenAI 互換 API を呼ぶプロバイダ（セルフホスト＝ティアA / Copilot＝ティアC）は
     * `choices[].finish_reason` をゲートウェイ側で正規化して返す
     * （`stop`→`end_turn` / `length`→`max_tokens` / `content_filter`→`refusal` /
     * `tool_calls`・`function_call`→`tool_use`。未知値は原文のまま透過し warn ログに残る）。
     * 呼び出し側がプロバイダごとに語彙を出し分ける必要はない。
     * - `refusal`: モデルが拒否した（安全性分類器による停止。OpenAI 互換の `content_filter` を含む）。
     *   **text は空**で返す（拒否直前の断片を下流の判断材料にしないため、ゲートウェイが破棄する）。
     *   「送信したが空応答」と混同してはならない。
     * - `max_tokens`: 出力上限に到達した。thinking が既定で有効なモデルでは本文が空または
     *   途中で切れる（IADR-0101）。断片は破棄せずそのまま返す。
     * - `end_turn`: 正常終了。
     */
  stopReason?: string | null;
}

