/**
 * FR-15 (#139), IADR-0046: 構成バージョン履歴の 1 エントリ。正データ源は GitOps 層（Git / ArgoCD の
 * 適用履歴）で、API は永続化せず注入されたスライスを返す。`hadDrift` はその時点のドリフト有無
 * （注入時に判明していれば設定、不明なら null＝画面は「—」と表示する）。
 * #520: **`required` を入れない**——C# の 4 メンバーがすべて nullable である（#518 の判断を再確認した）。
 */
export interface ConfigVersionEntryDto {
  gitCommit?: string | null;
  appliedAt?: string | null;
  appliedBy?: string | null;
  hadDrift?: boolean | null;
}

/**
 * 個々の不一致（自己申告到達不能は Unverifiable として縮退報告）
 */
export interface DriftFindingDto {
  kind: string;
  severity: string;
  target: string;
  detail: string;
}

/**
 * FR-15: 宣言（Git 上の pipeline.json）と実効構成のドリフト検出結果
 */
export interface DriftReportDto {
  hasDrift: boolean;
  checkedAt: string;
  findings: DriftFindingDto[];
}

/**
 * 機密区分（大文字小文字は無視）。confidential/restricted はティアA固定・外部送信しない
 */
export type EmbedApiRequestConfidentiality = typeof EmbedApiRequestConfidentiality[keyof typeof EmbedApiRequestConfidentiality] | null;


export const EmbedApiRequestConfidentiality = {
  public: 'public',
  internal: 'internal',
  confidential: 'confidential',
  restricted: 'restricted',
} as const;

/**
 * 用途。query は検索対象コレクションと次元を一致させるため既定外部経路へ固定
 */
export type EmbedApiRequestPurpose = typeof EmbedApiRequestPurpose[keyof typeof EmbedApiRequestPurpose];


export const EmbedApiRequestPurpose = {
  index: 'index',
  query: 'query',
} as const;

export interface EmbedApiRequest {
  /** 埋め込み対象テキスト（取り込みは本文全量を送るため機密区分で越境判定） */
  text: string;
  /** 機密区分（大文字小文字は無視）。confidential/restricted はティアA固定・外部送信しない */
  confidentiality?: EmbedApiRequestConfidentiality;
  /** 用途。query は検索対象コレクションと次元を一致させるため既定外部経路へ固定 */
  purpose?: EmbedApiRequestPurpose;
}

/**
 * embedded=false は機密区分による送信拒否（fail-closed）・次元不整合・呼び出し失敗を示す
 */
export interface EmbedApiResponse {
  vector: number[];
  dimensions: number;
  model: string;
  /** モデル別コレクション名 */
  collection: string;
  embedded: boolean;
  /** 選択・拒否した送信先（監査・縮退表示用） */
  endpoint?: string | null;
  /** 選択・拒否の理由（監査・縮退表示用） */
  routingReason?: string | null;
  /** true は一時障害（呼び出し側は再試行）。false は恒久理由（呼び出し側はスキップ） */
  retryable: boolean;
}

/**
 * FR-19, SC-19: 個人資料 1 件（台帳の投影）。**本文は含まない** ——
 * 本文編集は Obsidian 経路のみである（ADR-0046）。
 * `bytes` は**最新版のバイト数**であり、版履歴は容量に算入しない（ADR-0037 決定 16）。
 * `deleted` が真のとき `purgeAt` が完全削除の期限であり、SC-19 の「残り日数」と
 * 警告色（残り 7 日以内）の根拠になる。
 * 🔴 **所有者を運ぶ項目を持たない。** 誰の資料かは主体（JWT）で決まり、要求側が指定できない。
 */
export interface PrivateNoteDto {
  id: string;
  title: string;
  /** Obsidian Vault 内の相対パス（例 設計メモ.md） */
  vaultPath: string;
  /** 版番号。1 編集 = 1 版で進む */
  version: number;
  /** 最新版のバイト数（版履歴は算入しない） */
  bytes: number;
  /** 本文指紋。未同期の資料では null */
  contentHash?: string | null;
  /** 横断検索に含める（既定 false） */
  includeInSearch: boolean;
  /** ナレッジグラフに表示する（既定 false） */
  includeInGraph: boolean;
  /** AI の入力に含める（既定 false） */
  includeInAi: boolean;
  /** 論理削除済み（90 日は復元可） */
  deleted: boolean;
  deletedAt?: string | null;
  /** 完全削除の期限 */
  purgeAt?: string | null;
  createdAt: string;
  updatedAt: string;
}

/**
 * FR-19, SC-19, ADR-0037 決定 16・17: 保存容量の使用状況。
 * **算入するのは最新版と論理削除済み（90 日保管中）**であり、版履歴は算入しない。
 * `percent` は 80 / 95 / 100 の段階警告の判定に画面が使う。
 */
export interface PrivateNoteUsageDto {
  usedBytes: number;
  /** 既定 1 GB。管理者が最大 1 TB まで引き上げ可 */
  limitBytes: number;
  percent: number;
}

/**
 * FR-19, SC-19: 一覧（削除済みを含む）と容量表示を 1 応答で返す。 「うち削除済み」の内訳は画面が削除済み行の bytes を合算して出す（数え方を 2 つ持たない）。
 */
export interface PrivateNoteListResponse {
  usage: PrivateNoteUsageDto;
  notes: PrivateNoteDto[];
}

/**
 * FR-19, SC-19: 個人資料の新規作成。**タイトルのみで本文を受け取らない** （本画面にリッチエディタを描かない。ADR-0046 D-02）。
 */
export interface CreatePrivateNoteRequest {
  title: string;
  /** Obsidian Vault 内の相対パス。省略時は `<タイトル>.md` を後段が採る */
  vaultPath?: string | null;
}

/**
 * FR-19, SC-19, ADR-0037 決定 20: 完全削除（即時・復元不可）。 **単票も一括も同じ口**である（要素数の差でしかない）。
 */
export interface PurgePrivateNotesRequest {
  ids: string[];
}

/**
 * FR-19, SC-19: 完全削除の結果。`freedBytes` は確認ダイアログで示した 「解放される容量」の確定値である。
 */
export interface PurgePrivateNotesResponse {
  purgedCount: number;
  freedBytes: number;
}

/**
 * FR-19, SC-19, ADR-0037 決定 19・20: 論理削除の結果。
 * 🔴 `capacityFreed` は**常に false** である —— 「削除しても容量は空きません
 * （90 日間保管されます）」という SC-19 の固定文言の根拠を、散文ではなく機械可読な形で渡す。
 */
export interface PrivateNoteDeletedResponse {
  deletedAt?: string | null;
  /** 完全削除の期限 */
  purgeAt?: string | null;
  capacityFreed: boolean;
}

/**
 * FR-19, FR-20, SC-20: 露出 3 トグル（横断検索 / ナレッジグラフ / AI 入力）。 **既定はいずれも OFF・3 つは独立**である。
 */
export interface UpdateExposureRequest {
  includeInSearch: boolean;
  includeInGraph: boolean;
  includeInAi: boolean;
}

export type McpClientViewKind = typeof McpClientViewKind[keyof typeof McpClientViewKind];


export const McpClientViewKind = {
  interactive: 'interactive',
  'service-account': 'service-account',
} as const;

/**
 * 無人アカウントへ明示的に割り当てる ABAC 属性（機密区分上限・アクセス可能タグ等）
 */
export type McpClientViewAttributes = {[key: string]: string};

export type McpClientViewEgressTier = typeof McpClientViewEgressTier[keyof typeof McpClientViewEgressTier];


export const McpClientViewEgressTier = {
  'self-hosted': 'self-hosted',
  'protected-external': 'protected-external',
  'standard-external': 'standard-external',
} as const;

/**
 * FR-16, UC-09, SC-12: 登録済み MCP クライアント 1 件。
 * `kind` は `interactive`（有人）/ `service-account`（無人）の 2 値である。
 * `attributes` は**無人アカウントにだけ意味がある** —— 有人は利用者本人の属性で解決される。
 * `egressTier` はクライアント側 LLM のデータ保護水準であり、**未申告は最も低い水準へ倒れる**。
 */
export interface McpClientView {
  id: string;
  /** 認可サーバーのクライアント ID（トークンの azp / client_id） */
  clientId: string;
  displayName: string;
  kind: McpClientViewKind;
  /** false は次の呼び出しから即座に接続拒否 */
  enabled: boolean;
  /** 無人アカウントへ明示的に割り当てる ABAC 属性（機密区分上限・アクセス可能タグ等） */
  attributes: McpClientViewAttributes;
  egressTier: McpClientViewEgressTier;
  registeredAt: string;
  updatedAt: string;
}

export type RegisterMcpClientRequestKind = typeof RegisterMcpClientRequestKind[keyof typeof RegisterMcpClientRequestKind];


export const RegisterMcpClientRequestKind = {
  interactive: 'interactive',
  'service-account': 'service-account',
} as const;

export type RegisterMcpClientRequestAttributes = {[key: string]: string} | null;

export type RegisterMcpClientRequestEgressTier = typeof RegisterMcpClientRequestEgressTier[keyof typeof RegisterMcpClientRequestEgressTier] | null;


export const RegisterMcpClientRequestEgressTier = {
  'self-hosted': 'self-hosted',
  'protected-external': 'protected-external',
  'standard-external': 'standard-external',
} as const;

/**
 * FR-16, UC-09, SC-12: クライアント登録。`attributes` は**無人時に必須**であり、
 * 個人資料を読ませる割当は後段が 400 で拒否する。`egressTier` の未指定は
 * 最も低い保護水準（`standard-external`）として扱われる。
 */
export interface RegisterMcpClientRequest {
  clientId: string;
  displayName: string;
  kind: RegisterMcpClientRequestKind;
  attributes?: RegisterMcpClientRequestAttributes;
  egressTier?: RegisterMcpClientRequestEgressTier;
}

export type ReplaceMcpClientAttributesRequestAttributes = {[key: string]: string};

/**
 * FR-16, UC-09, SC-12: 無人アカウントの ABAC 属性割当の**差し替え**（部分更新ではない）。
 */
export interface ReplaceMcpClientAttributesRequest {
  attributes: ReplaceMcpClientAttributesRequestAttributes;
}

/**
 * FR-16, SC-12, ADR-0024 §5: 実効ツール 1 件（許可リスト ∩ 自己申告）。
 */
export interface PublishedToolView {
  /** 公開名 */
  name: string;
  /** 供給元サービス */
  service: string;
  description: string;
  requiredScope: string;
  egressClass: string;
}

/**
 * FR-16, SC-12, ADR-0024 §5: 許可リストと自己申告の食い違い 1 件。
 */
export interface ToolDriftView {
  kind: string;
  target: string;
  detail: string;
}

/**
 * FR-16, SC-12, ADR-0024 §5: 実効ツール一覧と構成ドリフト。
 * **書き込みの口は無い** —— 公開範囲の変更は Git 経由の公開構成変更で行う（GitOps）。
 */
export interface EffectiveToolsView {
  /** 収集した公開構成の版 */
  version: number;
  tools: PublishedToolView[];
  drifts: ToolDriftView[];
}

/**
 * FR-20, SC-20: 同期端末 1 件。**トークンは平文もハッシュも載らない。**
 * `active` は「未失効かつ期限内」であり、`expiresAt` との差から画面が
 * 「有効（残り日数）／期限切れ間近（残り 7 日以内）／期限切れ／失効」を描き分ける。
 */
export interface SyncDeviceDto {
  id: string;
  deviceName: string;
  issuedAt: string;
  /** 発行から 30 日 */
  expiresAt: string;
  revoked: boolean;
  /** 未同期なら null */
  lastSyncAt?: string | null;
  active: boolean;
}

/**
 * FR-20, SC-20, ADR-0037 決定 11: 端末登録（同期トークンの発行）。管理者承認を挟まない。
 */
export interface CreateSyncDeviceRequest {
  deviceName: string;
}

/**
 * FR-20, SC-20, ADR-0037 決定 12・15: 発行・再発行の応答。
 * 🔴 **`token`（平文）が現れるのはこの型だけである。** 保存されるのはハッシュのみで、
 * 一覧にも他のどの応答にも平文は載らない（発行直後に一度だけ表示・再表示不可）。
 * **自動更新（リフレッシュ）の口は存在しない** —— 更新は手動再発行だけである。
 */
export interface SyncTokenIssuedResponse {
  deviceId: string;
  deviceName: string;
  /** 平文の同期トークン。この応答でしか返らない */
  token: string;
  /** 発行から 30 日 */
  expiresAt: string;
}

/**
 * FR-20, SC-20, ADR-0037 決定 13: 全端末の一括失効の結果（端末紛失時の防御）。
 */
export interface RevokeAllSyncDevicesResponse {
  revokedCount: number;
}

/**
 * ABAC 属性（部門・機密区分上限・タグ）。1 キー 1 値
 */
export type PlatformUserDtoAttributes = {[key: string]: string};

/**
 * SC-17 主要素 1: 利用者一覧の 1 行（部門・ロール・ABAC 属性・状態）。
 * **部門は `attributes.department` である** —— 独立した項目として複写しない。
 */
export interface PlatformUserDto {
  /** 認可サーバーにおける利用者 ID */
  id: string;
  username: string;
  displayName: string;
  /** false は無効（全セッション失効済み） */
  enabled: boolean;
  /** 割り当て済みのロール（併任可） */
  roles: string[];
  /** ABAC 属性（部門・機密区分上限・タグ）。1 キー 1 値 */
  attributes: PlatformUserDtoAttributes;
}

export type ReplaceUserAttributesRequestAttributes = {[key: string]: string};

/**
 * SC-17: ABAC 属性の割当（**差し替え**。部分更新ではない）。
 * 部門と機密区分上限は必須、タグは任意。値・キーとも属性辞書（利用者スコープ）に
 * 定義済みのものだけを受け付ける。
 */
export interface ReplaceUserAttributesRequest {
  attributes: ReplaceUserAttributesRequestAttributes;
}

/**
 * SC-17: ロール割当（**差し替え**。併任可）。空集合は 400 ——
 * 権限を剥がすのではなく無効化を使う。
 */
export interface ReplaceUserRolesRequest {
  roles: string[];
}

export type BffAuthLoginParams = {
/**
 * ログイン後の戻り先。**自サイト内のパスに限る**（オープンリダイレクト防止）
 */
returnUrl?: string;
};

export type BffAuthLogoutParams = {
/**
 * セッションの sid。`/bff/auth/me` の `logoutUrl` が持つ値をそのまま使う
 */
sid: string;
/**
 * ログアウト後の戻り先。**自サイト内のパスに限る**
 */
returnUrl?: string;
};

export type BffFeedbackStatsParams = {
/**
 * 指定時はその回答に絞って集計する
 */
answerId?: string;
};

export type BffDashboardSummaryParams = {
/**
 * 集計期間（日数）。既定 7 日、上限 90 日にクランプ
 * @minimum 1
 * @maximum 90
 */
days?: number;
/**
 * 検索傾向で返す上位件数。既定 10、上限 50
 * @minimum 1
 * @maximum 50
 */
top?: number;
};

export type BffNotificationListParams = {
/**
 * true のとき未読のみを返す
 */
unreadOnly?: boolean;
/**
 * 取得件数。既定 50、上限 100 にクランプする
 * @minimum 1
 * @maximum 100
 */
limit?: number;
};

export type BffWikiSearchParams = {
/**
 * 検索語。空白のみなら 200 ＋ 空（後段が判定する）
 */
q?: string;
/**
 * 取得件数。既定 20、上限 50 へ後段がクランプする
 * @minimum 1
 * @maximum 50
 */
limit?: number;
};

export type BffConversionJobListParams = {
/**
 * 状態で絞り込む（`queued` / `processing` / `succeeded` / `failed`。「失敗のみ」フィルタの実体）
 */
status?: string;
};

export type BffConversionJobRetryParams = {
/**
 * **補正版を正とするための明示確認**（05_screens:333。IADR-0154 決定 4）。
 * 補正のあるジョブは既定で 409 `corrections_would_be_lost` になる。破棄してよい場合だけ
 * `true` を付けて再送する。**確認をダイアログだけに置かない**——生成クライアントや
 * 別経路の呼び出しが素通りするためである。
 */
discardCorrections?: boolean;
};

export type BffGraphNeighborsParams = {
/**
 * 探索の深さ。既定 2 / 上限 3（ADR-0034 決定 3）。上限超過は 400 で拒否し、黙って切り詰めない
 * @minimum 1
 * @maximum 3
 */
hops?: number;
/**
 * 間引きの基準（ADR-0049 決定 4）。表示上限（ノード 200）を超えた候補集合から何を残すか。
 * **未知の値・未指定は既定（distance）へ縮退する** —— 例外にしない。
 */
by?: BffGraphNeighborsBy;
/**
 * SC-18 (#917): 辺の型フィルタ（型 ID のカンマ区切り。未指定・空 = 絞らない）。
 * 🔴 **絞りはサーバ側で探索の入口に適用される**（planning#446）——クライアントで
 * 打ち切り後に絞ると「上位 200 件のうち一致したもの」になり範囲が意図せず狭まる。
 * 総数（totalNodes / totalEdges）もフィルタ後の母集合で数え直される。
 * GUID として読めない要素は 400（`edge_type_filter_invalid`）。**実在しない型 ID は
 * エラーにならず、単に 1 本も一致しない**（型辞書は公開済みの語彙であり秘匿対象ではない）。
 */
types?: string;
};

export type BffGraphNeighborsBy = typeof BffGraphNeighborsBy[keyof typeof BffGraphNeighborsBy];


export const BffGraphNeighborsBy = {
  distance: 'distance',
  updated: 'updated',
  degree: 'degree',
} as const;

export type BffGraphSuggestionsParams = {
/**
 * SC-21 (#918): 状態フィルタ。**未指定は `pending`（既定）**であり、`all` は絞りを外す。
 * 🔴 **`all` は状態の値ではない** —— 永続層に `all` という状態は存在しない。
 * 未知の値は 400（`invalid_state`）。**既定の補完も値域の検査も後段が一箇所で持つ**
 * （BFF は透過するだけである）。
 */
state?: BffGraphSuggestionsState;
/**
 * SC-21 (#918): 種類フィルタ。未指定は絞らない（＝すべて）。
 * 🔴 **リンク提案とタグ提案は同一の一覧に同居させる。画面を分けない**（FR-18）。
 * 未知の値は 400（`invalid_kind`）。
 */
kind?: BffGraphSuggestionsKind;
/**
 * 文書フィルタ。**その文書を両端のいずれかに持つ提案だけ**を返す
 * （タグ提案は対象文書 1 件を見る）。未指定は絞らない（＝権限内の全件）。
 * 🔴 **絞りは可視性の判定より前段に入る。** 判定そのものは端点の文書属性で行われ、
 * **この絞りは転送量を減らすだけで秘匿の実施点ではない**。
 * 🔴 **権限外・不存在の文書 ID でも 404 にはならない** —— 200 と空配列を返す。
 * 「その文書は無い」と「その文書の提案は 0 件」を区別させないためである。
 * 形式不正（UUID でない）のときだけ 400。
 */
documentId?: string;
};

export type BffGraphSuggestionsState = typeof BffGraphSuggestionsState[keyof typeof BffGraphSuggestionsState];


export const BffGraphSuggestionsState = {
  pending: 'pending',
  approved: 'approved',
  rejected: 'rejected',
  all: 'all',
} as const;

export type BffGraphSuggestionsKind = typeof BffGraphSuggestionsKind[keyof typeof BffGraphSuggestionsKind];


export const BffGraphSuggestionsKind = {
  link: 'link',
  tag: 'tag',
} as const;

